// Declarations in <cstdlib>
void std::exit(int status);   // Normal termination with cleanup
void std::abort();            // Abnormal termination, no cleanup

// Common exit status codes
EXIT_SUCCESS  // 0, successful termination
EXIT_FAILURE  // Non-zero, failed termination

// Typical usage patterns
assert(condition);           // Calls abort() if condition false
std::terminate();            // Calls abort() by default when exception handling fails

code_example:
#include <cstdlib>
#include <iostream>
#include <fstream>

class Resource {
public:
    Resource(const char* name) : name_(name) {
        std::cout << name_ << " constructed\n";
    }
    ~Resource() {
        std::cout << name_ << " destroyed\n";
    }
private:
    const char* name_;
};

static Resource global_resource("GlobalResource");

void cleanup_handler() {
    std::cout << "atexit handler called\n";
}

void demonstrate_exit() {
    Resource local_resource("LocalResource");
    std::atexit(cleanup_handler);

    std::cout << "Calling std::exit(0)...\n";
    std::exit(0);  // Cleanup: atexit handler + global destructor
                   // NO cleanup: local_resource destructor NOT called
}

void demonstrate_abort() {
    Resource local_resource("LocalResource");
    std::atexit(cleanup_handler);

    std::cout << "Calling std::abort()...\n";
    std::abort();  // NO cleanup at all - immediate termination
}

int main() {
    std::cout << "=== Demonstrating exit vs abort ===\n";

    // Uncomment ONE to test:
    // demonstrate_exit();
    // demonstrate_abort();

    // Using exit:
    // Output: GlobalResource constructed
    //         LocalResource constructed
    //         Calling std::exit(0)...
    //         atexit handler called
    //         GlobalResource destroyed
    //         (LocalResource NOT destroyed - automatic object)

    // Using abort:
    // Output: GlobalResource constructed
    //         LocalResource constructed
    //         Calling std::abort()...
    //         Aborted (core dumped)
    //         (NO destructors called, NO atexit handlers)

    return 0;
}
